`timescale 1ps/1ps
// Column-shared Booth, INT16 only: 15 signed random 16x16 matrix pairs, 3840 output checks.
// Pure Verilog-2001. Reference matrices are embedded; no external .mem path.
// Define CONTROLLED at compile time for the top-level FSM wrapper.
// Source stream is UNSKEWED; input skewing is inside synthesizable RTL.
module tb_skew_fsm_int16;
    localparam integer N = 16;
    localparam integer WIDTH = 16;
    reg clk = 1'b0;
    always #1650 clk = ~clk; // 3.300 ns = 3300 ps

    reg rst_n = 1'b0;
    reg [1:0] mode_in = 2'b11;
    reg clear_tile = 1'b0;
    reg [255:0] A_left_flat = 256'b0;
    reg [255:0] B_top_flat = 256'b0;
    reg [15:0] A_left_valid = 16'b0;
    reg [15:0] B_top_valid = 16'b0;
    wire [9215:0] C_flat;
    wire tile_done;
    reg start = 1'b0;
    reg stream_last = 1'b0;
    wire busy, done, run_active, feed_ready;

`ifdef SKEW_FSM
    column_shared_skew_fsm_16x16 dut (
        .clk(clk), .rst_n(rst_n), .start(start),
        .mode_in(mode_in), .A_rows_flat(A_left_flat),
        .B_cols_flat(B_top_flat), .C_flat(C_flat),
        .busy(busy), .done(done), .run_active(run_active),
        .feed_ready(feed_ready)
    );
    assign tile_done = done;
`else
    systolic_array_16x16 dut (
        .clk(clk), .rst_n(rst_n), .mode_in(mode_in),
        .clear_tile(clear_tile),
        .A_left_flat(A_left_flat), .B_top_flat(B_top_flat),
        .A_left_valid(A_left_valid), .B_top_valid(B_top_valid),
        .C_flat(C_flat), .tile_done(tile_done)
    );
`endif

    reg [15:0] A_mem [0:255];
    reg [15:0] B_mem [0:255];
    reg [35:0] C_ref [0:255];
    reg [35:0] acc_mask;
    reg [35:0] rtl_value;
    reg signed [63:0] sw_sum;
    reg [35:0] sw_value;
    integer mode_idx, case_idx, t, row, col, k, waits;
    localparam integer SELECTED_MODE = 16;
    localparam integer SELECTED_MODE_INDEX = 2;
    integer only_mode = SELECTED_MODE; // fixed for this standalone testbench
    integer cases_per_mode = 15;
    integer zero_pad = 1; // default: zero-pad INT4/INT8 external 16-bit inputs
    integer expected_tests;
    integer failures = 0;
    integer checks = 0;
    integer tests = 0;
    reg [4095:0] vector_A, vector_B;
    reg [9215:0] vector_C;


    function automatic [35:0] precision_mask(input integer mode_index);
        begin
            case (mode_index)
                0: precision_mask = 36'h000000FFF;
                1: precision_mask = 36'h0000FFFFF;
                default: precision_mask = 36'hFFFFFFFFF;
            endcase
        end
    endfunction

    // Keeps signed values in A_mem/B_mem for independent golden calculation,
    // while exercising a zero-padded low-precision external operand interface.
    // The PE's Booth multiplier sign-extends the active precision internally.
    // +ZERO_PAD=0 optionally reproduces legacy sign-extended input traffic.
    function automatic [15:0] forward_input_encoding(
        input [15:0] signed_word, input integer mi
    );
        begin
            if (!zero_pad) forward_input_encoding = signed_word;
            else case (mi)
                0: forward_input_encoding = {12'b0, signed_word[3:0]};
                1: forward_input_encoding = {8'b0,  signed_word[7:0]};
                default: forward_input_encoding = signed_word;
            endcase
        end
    endfunction

`ifdef SKEW_FSM
`define ARRAY dut.u_array
`else
`define ARRAY dut
`endif

    // The source provides ALL rows of A and ALL columns of B in parallel,
    // with the same k on a given clock. Only synthesizable DUT logic skews them.
    task automatic drive_unskewed(input integer k_index);
        integer r, c;
        begin
            A_left_flat = 256'b0;
            B_top_flat = 256'b0;
            A_left_valid = 16'b0;
            B_top_valid  = 16'b0;
            if (k_index >= 0 && k_index < N) begin
                for (r=0; r<N; r=r+1)
                    A_left_flat[r*16 +: 16] = forward_input_encoding(
                        A_mem[r*N+k_index], mode_idx);
                for (c=0; c<N; c=c+1)
                    B_top_flat[c*16 +: 16] = forward_input_encoding(
                        B_mem[k_index*N+c], mode_idx);
            end
        end
    endtask

    // Verify the actual forwarding network has no inactive upper bits.
    // This checks *all 256 PE outputs*, not just left/top input encoding.
    task automatic check_forwarding_masks;
        integer rr, cc;
        reg [15:0] legal_mask;
        reg [23:0] booth_mask;
        begin
            case (mode_idx)
                0: begin legal_mask = 16'h000F; booth_mask=24'h00003F; end
                1: begin legal_mask = 16'h00FF; booth_mask=24'h000FFF; end
                default: begin legal_mask = 16'hFFFF; booth_mask=24'hFFFFFF; end
            endcase
            for (rr=0; rr<N; rr=rr+1)
                for (cc=0; cc<N; cc=cc+1) begin
                    if ((`ARRAY.a_forward[rr][cc] & ~legal_mask) !== 16'b0 ||
                        (`ARRAY.booth_forward[rr][cc] & ~booth_mask) !== 24'b0)
                        begin $display("FORWARD_MASK_FAIL mode=%0d case=%0d PE[%0d][%0d] A=%h B=%h",
                               mode_idx,case_idx,rr,cc,
                               `ARRAY.a_forward[rr][cc],`ARRAY.booth_forward[rr][cc]); $stop; end
                end
        end
    endtask

    task automatic drive_edges(input integer cycle_index);
        integer r, c, idx;
        begin
            A_left_flat = 256'b0;
            B_top_flat = 256'b0;
            A_left_valid = 16'b0;
            B_top_valid = 16'b0;
            for (r=0; r<N; r=r+1) begin
                idx = cycle_index - r;
                if (idx >= 0 && idx < N) begin
                    A_left_flat[r*16 +: 16] = forward_input_encoding(A_mem[r*N + idx], mode_idx);
                    A_left_valid[r] = 1'b1;
                end
            end
            for (c=0; c<N; c=c+1) begin
                idx = cycle_index - c;
                if (idx >= 0 && idx < N) begin
                    B_top_flat[c*16 +: 16] = forward_input_encoding(B_mem[idx*N + c], mode_idx);
                    B_top_valid[c] = 1'b1;
                end
            end
        end
    endtask

    // Glitch-free ICG latches sample enable only during the LOW clock phase.
    // CLEAR deliberately enables every gate to reset its register slices.
    // On the CLEAR -> RUN rising edge, the old gate enable remains latched
    // until the NEXT falling edge. Do not require precision-specific gate
    // states on this transition edge; check again after a full LOW phase.
    reg gate_check_armed = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) gate_check_armed <= 1'b0;
        else begin
`ifdef SKEW_FSM
            gate_check_armed <= run_active && (mode_in != 2'b11);
`else
            gate_check_armed <= !clear_tile && (mode_in != 2'b11);
`endif
        end
    end

    // Spot-check both corner PEs at 1 ps after rising edge, when the
    // precision selection has already passed through the low latch phase.
    // Full A/B precision mask is independently checked at all 256 PE ports.
    always @(posedge clk) begin
        #1;
        `ifdef SKEW_FSM
        if (rst_n && gate_check_armed && run_active && mode_in != 2'b11) begin
`else
        if (rst_n && gate_check_armed && !clear_tile && mode_in != 2'b11) begin
`endif
            if (mode_in == 2'b00) begin
                if (`ARRAY.GEN_ROW[0].GEN_COL[0].u_pe.clk_forward_mid !== 1'b0 ||
                    `ARRAY.GEN_ROW[0].GEN_COL[0].u_pe.clk_forward_high !== 1'b0 ||
                    `ARRAY.GEN_ROW[15].GEN_COL[15].u_pe.clk_forward_mid !== 1'b0 ||
                    `ARRAY.GEN_ROW[15].GEN_COL[15].u_pe.clk_forward_high !== 1'b0)
                    begin $display("INT4_FORWARD_CLOCK_GATING_FAIL"); $stop; end
            end else if (mode_in == 2'b01) begin
                if (`ARRAY.GEN_ROW[0].GEN_COL[0].u_pe.clk_forward_mid !== 1'b1 ||
                    `ARRAY.GEN_ROW[0].GEN_COL[0].u_pe.clk_forward_high !== 1'b0 ||
                    `ARRAY.GEN_ROW[15].GEN_COL[15].u_pe.clk_forward_mid !== 1'b1 ||
                    `ARRAY.GEN_ROW[15].GEN_COL[15].u_pe.clk_forward_high !== 1'b0)
                    begin $display("INT8_FORWARD_CLOCK_GATING_FAIL"); $stop; end
            end else if (mode_in == 2'b10) begin
                if (`ARRAY.GEN_ROW[0].GEN_COL[0].u_pe.clk_forward_mid !== 1'b1 ||
                    `ARRAY.GEN_ROW[0].GEN_COL[0].u_pe.clk_forward_high !== 1'b1 ||
                    `ARRAY.GEN_ROW[15].GEN_COL[15].u_pe.clk_forward_mid !== 1'b1 ||
                    `ARRAY.GEN_ROW[15].GEN_COL[15].u_pe.clk_forward_high !== 1'b1)
                    begin $display("INT16_FORWARD_CLOCK_GATING_FAIL"); $stop; end
            end
        end
    end

    initial begin
        // Vivado/XSim VCD is controlled by scripts/xsim_vcd_INT*.tcl.
        // Use the supplied batch runner with +MODE=4/8/16 so each VCD
        // contains exactly one precision mode (default 15 fully random 16x16 tiles).
        // Do not use $dumpvars for XSim: open_vcd/log_vcd are the
        // documented supported interface.
`ifdef IVERILOG_VCD
        if ($test$plusargs("VCD")) begin
            $dumpfile("sim/systolic16x16_iverilog.vcd");
            $dumpvars(0, tb_skew_fsm_int16.dut);
        end
`endif
        only_mode = SELECTED_MODE; // intentionally ignore +MODE; this bench tests only one mode
        if (only_mode != 0 && only_mode != 4 && only_mode != 8 && only_mode != 16)
            begin $display("Bad +MODE=%0d; expected 4,8,16 or omitted", only_mode); $stop; end
        if (!$value$plusargs("CASES=%d", cases_per_mode)) cases_per_mode=15;
        if (cases_per_mode < 1 || cases_per_mode > 15)
            begin $display("Bad +CASES=%0d; expected 1..15", cases_per_mode); $stop; end
        if ($value$plusargs("ZERO_PAD=%d", zero_pad)) begin
            if (zero_pad != 0 && zero_pad != 1)
                begin $display("Bad ZERO_PAD; expected 0 or 1"); $stop; end
        end
        expected_tests = (only_mode == 0) ? 3*cases_per_mode : cases_per_mode;
        $display("VCD_RUN_CONFIG requested_MODE=%0d expected_tiles=%0d clock_ps=3300 zero_pad=%0d",
                 only_mode, expected_tests, zero_pad);
        repeat (4) @(negedge clk);
        rst_n = 1'b1;
        $display("BEGIN 16x16 SIGNED MATRIX REGRESSION (%0d tiles)", expected_tests);
        for (mode_idx=SELECTED_MODE_INDEX; mode_idx<=SELECTED_MODE_INDEX; mode_idx=mode_idx+1) begin
          if (only_mode == 0 ||
              (only_mode == 4  && mode_idx == 0) ||
              (only_mode == 8  && mode_idx == 1) ||
              (only_mode == 16 && mode_idx == 2)) begin
            acc_mask = precision_mask(mode_idx);
            for (case_idx=0; case_idx<cases_per_mode; case_idx=case_idx+1) begin
                // Memory-independent ROM: exact original reference .mem contents
                // embedded at package creation. No $readmemh or host file paths.
                case (mode_idx*16 + case_idx)
                  32: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  33: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  34: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  35: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  36: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  37: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  38: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  39: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  40: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  41: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  42: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  43: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  44: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  45: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  46: begin
                      vector_A=4096';
                      vector_B=4096';
                      vector_C=9216';
                  end
                  default: begin
                      $display("ERROR: missing embedded reference mode_index=%0d case=%0d",mode_idx,case_idx);
                      $stop;
                  end
                endcase
                for (k=0;k<256;k=k+1) begin
                    A_mem[k]=vector_A[k*16 +: 16];
                    B_mem[k]=vector_B[k*16 +: 16];
                    C_ref[k]=vector_C[k*36 +: 36];
                end

                // Independently check Python-generated golden results using
                // SV signed dot-products before evaluating RTL output.
                for (row=0; row<N; row=row+1) begin
                    for (col=0; col<N; col=col+1) begin
                        sw_sum = 64'sd0;
                        for (k=0; k<N; k=k+1)
                            sw_sum = sw_sum + $signed(A_mem[row*N+k]) *
                                                 $signed(B_mem[k*N+col]);
                        sw_value = sw_sum[35:0] & acc_mask;
                        if (sw_value !== C_ref[row*N+col]) begin
                            $display("BAD_VECTOR mode=%0d case=%0d row=%0d col=%0d sv=%h py=%h",
                                     mode_idx, case_idx, row, col,
                                     sw_value, C_ref[row*N+col]);
                            begin $display("Python vector/scoreboard disagreement"); $stop; end
                        end
                    end
                end

                // No testbench skew: provide all rows/columns simultaneously at k=0..15.
                A_left_flat = 256'b0;
                B_top_flat = 256'b0;
                A_left_valid = 16'b0;
                B_top_valid = 16'b0;
                mode_in = mode_idx[1:0];
`ifdef SKEW_FSM
                // Controller CLEAR/RUN/DRAIN/DONE sequencing.
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                wait (feed_ready === 1'b1);
                @(negedge clk);
`else
                clear_tile = 1'b1;
                @(negedge clk);
                clear_tile = 1'b0;
`endif
                for (t=0; t<N; t=t+1) begin
                    drive_unskewed(t);
`ifdef SKEW_FSM
                    // stream_last generated internally when feed_cycle==15; no external skew.
`endif
                    @(negedge clk);
                    check_forwarding_masks();
                end
`ifdef SKEW_FSM
                stream_last = 1'b0;
`endif
                drive_unskewed(N); // drives zeros; skew registers drain in hardware

                // The new DUT includes the full physical delay network.
                // At this point input injection is over, but skew shifting
                // remains active until core_tile_done is asserted.

                // Wait for the full one-stage-Booth-pipeline drain. Do not
                // check early outputs before the bottom-right PE is finished.
                waits = 0;
                while (tile_done !== 1'b1 && waits < 80) begin
                    @(negedge clk);
                    check_forwarding_masks();
                    waits = waits + 1;
                end
                if (tile_done !== 1'b1)
                    begin $display("TIMEOUT mode=%0d case=%0d last_PE_mac_count=%0d",
                           mode_idx, case_idx, `ARRAY.last_pe_products); $stop; end

                // All 256 output-stationary PE accumulators are now final.
                for (row=0; row<N; row=row+1) begin
                    for (col=0; col<N; col=col+1) begin
                        rtl_value = C_flat[((row*N+col)*36) +: 36] & acc_mask;
                        checks = checks + 1;
                        if (rtl_value !== C_ref[row*N+col]) begin
                            failures = failures + 1;
                            if (failures <= 25)
                                $display("FAIL mode=INT%0d case=%0d C[%0d][%0d] RTL=%h EXPECT=%h",
                                     (mode_idx==0)?4:((mode_idx==1)?8:16),
                                     case_idx, row, col, rtl_value,
                                     C_ref[row*N+col]);
                        end
                    end
                end
                tests = tests + 1;
                $display("TEST %02d/%0d INT%0d case=%0d output_checks=%0d total_failures=%0d",
                    tests, expected_tests, (mode_idx==0)?4:((mode_idx==1)?8:16),
                    case_idx, checks, failures);
            end
          end // selected precision mode
        end
        $display("RESULT tests=%0d checks=%0d failures=%0d", tests, checks, failures);
        if (tests != expected_tests || checks != expected_tests*256 || failures != 0)
            begin $display("SYSTOLIC_16x16_FAIL"); $stop; end
        $display("SYSTOLIC_16x16_PASS: %0d matrix tests, %0d output checks, MODE=%0d",
                 tests, checks, only_mode);
        $finish;
    end
endmodule
